import os, json, csv, hashlib
from pathlib import Path
from openpyxl import load_workbook

paths = [
 r'D:\\下载文件\\Competitor-US-Last-30-days-217940.xlsx',
 r'E:\\Desktop\\所有商品报告_08-26-2026.txt',
 r'E:\\Desktop\\4A_VC的item整理_2026-08-11.xlsx',
 r'D:\\下载文件\\amazon_df_inv_bulk_2026-08-27_10_30_57_UTC_dataset_0.csv',
]

def clean(v):
    if v is None: return None
    s = str(v).replace('\\r',' ').replace('\\n',' ')
    return s[:180]

def digest(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for b in iter(lambda:f.read(1024*1024), b''): h.update(b)
    return h.hexdigest()

def inspect_xlsx(p):
    wb = load_workbook(p, read_only=True, data_only=True)
    sheets=[]
    for ws in wb.worksheets:
        sampled=[]
        header_candidates=[]
        for idx,row in enumerate(ws.iter_rows(min_row=1, max_row=min(ws.max_row,15), values_only=True), start=1):
            vals=[clean(v) for v in row]
            last=max((i for i,v in enumerate(vals) if v not in (None,'')), default=-1)
            vals=vals[:last+1]
            sampled.append({'row':idx,'values':vals})
            header_candidates.append((sum(v not in (None,'') for v in vals), idx, vals))
        header_candidates.sort(reverse=True, key=lambda x:(x[0],-x[1]))
        sheets.append({
          'name':ws.title,'max_row':ws.max_row,'max_column':ws.max_column,
          'likely_header_row': header_candidates[0][1] if header_candidates else None,
          'likely_headers': header_candidates[0][2] if header_candidates else [],
          'sample_rows':sampled[:8]
        })
    return sheets

def decode_text(p):
    raw=Path(p).read_bytes()
    for enc in ('utf-8-sig','utf-16','gb18030','latin-1'):
        try:
            return enc, raw.decode(enc)
        except UnicodeDecodeError:
            pass

def inspect_delimited(p):
    enc,text=decode_text(p)
    lines=text.splitlines()
    probe='\\n'.join(lines[:30])
    try:
        dialect=csv.Sniffer().sniff(probe, delimiters='\\t,;|')
        delim=dialect.delimiter
    except Exception:
        delim='\\t' if '\\t' in (lines[0] if lines else '') else ','
    rows=list(csv.reader(lines, delimiter=delim))
    maxcols=max((len(x) for x in rows), default=0)
    return {'encoding':enc,'delimiter':repr(delim),'row_count_including_header':len(rows),'max_columns':maxcols,'sample_rows':[[clean(v) for v in x] for x in rows[:5]]}

out=[]
for p in paths:
    item={'path':p,'size':os.path.getsize(p),'sha256':digest(p)}
    if p.lower().endswith('.xlsx'):
        item['xlsx']=inspect_xlsx(p)
    else:
        item['delimited']=inspect_delimited(p)
    out.append(item)
print(json.dumps(out,ensure_ascii=False,indent=2))
