const outputDir = `${root}/outputs/vc-sc-audit-20260830`;
await fs.mkdir(outputDir, { recursive: true });

const wb = Workbook.create();
const colors = {
  navy: "#17324D",
  teal: "#0F766E",
  teal2: "#D9F0ED",
  blue: "#DCEAF7",
  gold: "#E9A23B",
  paleGold: "#FFF3D6",
  red: "#B42318",
  paleRed: "#FDE7E4",
  green: "#207A4A",
  paleGreen: "#E4F3EA",
  gray: "#64748B",
  paleGray: "#F3F6F8",
  line: "#D7DEE5",
  white: "#FFFFFF",
  ink: "#1F2937",
};

function colName(n) {
  let s = "";
  while (n > 0) {
    n--;
    s = String.fromCharCode(65 + (n % 26)) + s;
    n = Math.floor(n / 26);
  }
  return s;
}

function styleTitle(sheet, title, subtitle, lastCol) {
  const end = colName(lastCol);
  sheet.mergeCells(`A1:${end}1`);
  sheet.getRange("A1").values = [[title]];
  sheet.getRange("A1").format = {
    fill: colors.navy,
    font: { bold: true, color: colors.white, size: 20 },
    verticalAlignment: "center",
  };
  sheet.getRange("A1").format.rowHeight = 34;
  sheet.mergeCells(`A2:${end}2`);
  sheet.getRange("A2").values = [[subtitle]];
  sheet.getRange("A2").format = {
    fill: "#EAF0F5",
    font: { color: colors.ink, size: 10 },
    wrapText: true,
    verticalAlignment: "center",
  };
  sheet.getRange("A2").format.rowHeight = 34;
}

function addDataSheet(name, title, subtitle, headers, rows, widths, options = {}) {
  const sheet = wb.worksheets.add(name);
  sheet.showGridLines = false;
  styleTitle(sheet, title, subtitle, headers.length);
  const lastCol = colName(headers.length);
  sheet.getRange(`A4:${lastCol}4`).values = [headers];
  sheet.getRange(`A4:${lastCol}4`).format = {
    fill: colors.teal,
    font: { bold: true, color: colors.white },
    verticalAlignment: "center",
    wrapText: true,
    borders: { preset: "inside", style: "thin", color: "#5AA39B" },
  };
  sheet.getRange(`A4:${lastCol}4`).format.rowHeight = 30;
  if (rows.length) {
    sheet.getRange(`A5:${lastCol}${rows.length + 4}`).values = rows;
    sheet.getRange(`A5:${lastCol}${rows.length + 4}`).format = {
      font: { color: colors.ink, size: 9 },
      verticalAlignment: "top",
      borders: { insideHorizontal: { style: "thin", color: "#E5EAF0" } },
    };
    if (options.wrapCols) {
      for (const c of options.wrapCols) sheet.getRange(`${c}5:${c}${rows.length + 4}`).format.wrapText = true;
    }
    const table = sheet.tables.add(`A4:${lastCol}${rows.length + 4}`, true, `${name.replace(/[^A-Za-z0-9]/g, "") || "Data"}Table`);
    table.style = "TableStyleMedium2";
    table.showFilterButton = true;
  }
  sheet.freezePanes.freezeRows(4);
  sheet.freezePanes.freezeColumns(options.freezeCols || 2);
  widths.forEach((w, i) => { sheet.getRange(`${colName(i + 1)}:${colName(i + 1)}`).format.columnWidth = w; });
  if (options.ratingCol && rows.length) sheet.getRange(`${options.ratingCol}5:${options.ratingCol}${rows.length + 4}`).format.numberFormat = "0.0";
  if (options.countCol && rows.length) sheet.getRange(`${options.countCol}5:${options.countCol}${rows.length + 4}`).format.numberFormat = "0";
  if (options.urlCol && rows.length) sheet.getRange(`${options.urlCol}5:${options.urlCol}${rows.length + 4}`).format.font = { color: "#0563C1", underline: true, size: 9 };
  if (options.statusValidation && rows.length) {
    sheet.getRange(`${options.statusValidation}5:${options.statusValidation}${rows.length + 4}`).dataValidation = {
      rule: { type: "list", values: ["未开始", "核验中", "已完成", "不处理"] },
    };
  }
  return sheet;
}

