import { FileBlob, SpreadsheetFile } from "@oai/artifact-tool";

const [firstPath, secondPath, auditPath] = process.argv.slice(2);
const firstWb = await SpreadsheetFile.importXlsx(await FileBlob.load(firstPath));
const secondWb = await SpreadsheetFile.importXlsx(await FileBlob.load(secondPath));
const auditWb = await SpreadsheetFile.importXlsx(await FileBlob.load(auditPath));

const firstSheet = firstWb.worksheets.getItemAt(0);
const secondSheet = secondWb.worksheets.getItemAt(0);
const auditSheet = auditWb.worksheets.getItem("评分待补81");
const firstRange = firstSheet.getUsedRange(true);
const secondRange = secondSheet.getUsedRange(true);
const firstValues = firstRange.values;
const secondValues = secondRange.values;
const targetValues = auditSheet.getRange("A5:A85").values.flat().filter(Boolean).map(String);

const firstAsins = firstValues.slice(1).map(r => r[0]).filter(Boolean).map(String);
const secondAsins = secondValues.slice(1).map(r => r[0]).filter(Boolean).map(String);
const combined = new Set([...firstAsins, ...secondAsins]);
const targetSet = new Set(targetValues);

console.log(JSON.stringify({
  first: { sheet: firstSheet.name, range: firstRange.address, rows: firstAsins.length, targetMatches: firstAsins.filter(x => targetSet.has(x)).length },
  second: { sheet: secondSheet.name, range: secondRange.address, rows: secondAsins.length, targetMatches: secondAsins.filter(x => targetSet.has(x)).length },
  combinedTargetMatches: targetValues.filter(x => combined.has(x)).length,
  stillMissing: targetValues.filter(x => !combined.has(x)),
  secondExtras: secondAsins.filter(x => !targetSet.has(x)),
}, null, 2));

