  navy: "#17365D",
  teal: "#0F6B78",
  paleBlue: "#DDEBF7",
  paleGreen: "#E2F0D9",
  paleYellow: "#FFF2CC",
  paleRed: "#FCE4D6",
  gray: "#E7E6E6",
  darkGray: "#595959",
  white: "#FFFFFF",
  line: "#B4C6E7",
};

function setTitle(sheet, endCol, title, subtitle) {
  sheet.showGridLines = false;
  sheet.getRange(`A1:${endCol}1`).merge();
  sheet.getRange("A1").values = [[title]];
  sheet.getRange(`A2:${endCol}2`).merge();
  sheet.getRange("A2").values = [[subtitle]];
  sheet.getRange(`A1:${endCol}1`).format = {
    fill: colors.navy,
    font: { bold: true, color: colors.white, size: 16 },
    verticalAlignment: "center",
  };
  sheet.getRange(`A2:${endCol}2`).format = {
    fill: colors.paleBlue,
    font: { color: colors.darkGray, italic: true, size: 10 },
    wrapText: true,
    verticalAlignment: "center",
  };
  sheet.getRange("1:1").format.rowHeight = 30;
  sheet.getRange("2:2").format.rowHeight = 34;
}

function styleHeader(range) {
  range.format = {
    fill: colors.teal,
    font: { bold: true, color: colors.white },
    wrapText: true,
    verticalAlignment: "center",
  };
  range.format.rowHeight = 34;
}

function applyStatusFormatting(range) {
  range.conditionalFormats.add("containsText", { text: "已确认", format: { fill: colors.paleGreen, font: { color: "#006100" } } });
